    "巨钳螳螂": "ハッサム",
    "巨钳蟹": "キングラー",
    "已关闭": "オフ",
    "已击败": "撃破済み",
    "已到下限": "これ以上下がらない",
    "已售出": "売り切れ",
    "已导出 oasis-save.json": "oasis-save.json を書き出した",
    "已开启": "ON",
    "已收入囊中": "手に入れた",
    "已收录": "登録済み",
    "已收录的宝可梦（遇见过就算，打赢过的会打上 ✓）": "登録したポケモン（出会えば登録。勝つと撃破マークが付く）",
    "已收进手持栏（{n} / {max}）": "手持ちスロットに入れた（{n} / {max}）",
    "已收集的卡牌种类（拿到过就算，重复的不另算）": "集めたカードの種類（一度でも手に入れれば数える。重複は数えない）",
    "已经休息过了（回了 {n} 点）。": "もう休んでいる（{n} 回復した）。",
    "已经休息过了（当时是满血）。": "もう休んでいる（そのときは満タンだった）。",
    "已经把「{card}」换掉了（{from} → {to}）。": "「{card}」を交換した（{from} → {to}）。",
    "已见过": "見たことあり",
    "已见过的道具（拿到过一次就算）": "見たことのあるアイテム（一度手に入れれば登録）",
    "已静音": "ミュート",
    "布歪了也没关系，你肯留下吗": "布が曲がっても、そばにいてくれる？",
    "带电的风": "帯電した風",
    "带粗体的是这一版最值得看的几件事。": "太字の項目は、このバージョンで特に見てほしいところだ。",
    "带走一颗果子（获得好伤药 ×2）": "実をひとつ持ち帰る（キズぐすり ×2 獲得）",
    "带进战斗的就是你拥有的全部卡牌 —— 不能挑着不带，也不能只带两张。": "戦闘に持ち込むのは持っているカード全部 —— 選んで外すことも、2 枚だけにすることもできない。",
    "干干净净一根，商人都认得这个价钱。": "きれいな一本、商人ならその値打ちを知っている。",
    "幸运": "幸運",
    "幸运 +{n}": "運 +{n}",
    "幸运 {luck}：暴击 {crit}%，闪避 {dodge}%": "幸運 {luck}：会心 {crit}%、回避 {dodge}%",
    "幸运咒语": "ラッキーチャーム",
    "幸运护符": "ラッキーチャーム",
    "幸运蛋": "しあわせタマゴ",
    "幸运：暴击率与闪避率。": "幸運：会心率と回避率。",
    "幸运：暴击率与闪避率，暴击伤害 ×{mult}。": "幸運：会心率と回避率。会心ダメージは ×{mult}。",
    "幻象光线": "サイケこうせん",
    "幽灵": "ゴースト",
    "幽灵宝石": "ゴーストジュエル",
    "广域破坏": "ワイドブレイカー",
    "广域防守": "ワイドガード",
    "底下是一堆蛋壳，壳里塞着别人藏起来的药，居然还没坏。\n「谁藏的？我先借走咯。」\n获得{item} ×1。": "下にあったのは卵の殻の山で、殻の中には誰かが隠した薬が詰まっていた。まだ傷んでいない。\n「誰が隠したの？　先に借りていくね。」\n{item} ×1 を手に入れた。",
    "庞岩怪": "ギガイアス",
    "开始新的冒险": "新しく冒険を始める",
    "开打前嚼一片，身上那点晦气就散了。": "戦う前にひとかじり、ついてないのも消えていく。",
    "开！": "開ける！",
    "弃牌": "捨て札",
    "弃牌：打出去的牌会进这里（不进牌堆）。牌堆抽空、还要再抽的时候，这里才洗回牌堆。": "捨て札：出したカードはここに入る（山札には戻らない）。山札が空になって、さらにドローするときだけここが山札に戻る。",
    "弃牌：把牌弃进弃牌堆（牌堆抽空时会洗回来）。": "捨て札：カードを捨て札置き場へ捨てる（山札が尽きたときはシャッフルして戻ってくる）。",
    "弃牌：进弃牌堆，牌堆抽空时会洗净再抽回来。": "捨て札：捨て札置き場に入り、山札が尽きたときにシャッフルして再び引いてくる。",
    "引爆": "起爆",
    "引爆 ×{n}": "起爆 ×{n}",
    "引爆了 {name} 身上 {n} 层持续伤害！": "{name}のスリップダメージ {n} 層を起爆した！",
    "引爆对手身上所有中毒 / 剧毒 / 灼伤层数，立刻结算并清空。使用后销毁。": "相手のどく / もうどく / やけどを全部爆発させ、ただちに精算して消し去る。使用後消滅。",
    "引爆持续伤害": "継続ダメージを爆発",
    "引雷的铁杆": "雷を呼ぶ鉄の棒",
    "张开翅膀扇散它！": "翼を広げて追い払ってやる！",
    "张开翅膀扇散它（-8 HP，敏捷 +2）": "翼を広げて追い払う（-8 HP、敏捷 +2）",
    "张开翅膀迎着风。": "風に向かってハネを広げる。",
    "张开翅膀迎着风！": "翼を広げて風を受け止める！",
    "张开翅膀迎着风（攻击 +4，-10 HP）": "翼を広げて風を受ける（攻撃 +4、-10 HP）",
    "张着嘴在沙里横冲直撞，撞完还要抬头看看有没有撞对。": "口を開けたまま砂を突っ走り、ぶつかってから確かめる。",
    "张着嘴蹲在岩阴里，等东西自己撞上来。": "口を開けて岩陰にしゃがみ、何かがぶつかるのを待つ。",
    "弱丁鱼": "ヨワシ",
    "弱丁鱼渔市": "ヨワシ魚市場",
    "强化自己：本场战斗里自己的属性提升。": "自分を強化：この戦闘中、自分の能力が上がる。",
