    "当前被削弱了 {n} 点。": "現在 {n} ポイント弱体化している。",
    "彗星拳": "コメットパンチ",
    "彗星碎片": "すいせいのかけら",
    "影子偷袭": "かげうち",
    "影子先到了，笑声后到。": "影が先に着いて、笑い声が後から来る。",
    "影子先动了一寸，你才听见笑声。": "影が一寸先に動いて、それから笑い声が聞こえる。",
    "影子先替你守了夜，你可以慢慢走。": "影が先に君の夜を守る、ゆっくり行けばいい。",
    "影子里躲久了，正好活动活动": "影の中に潜んでばかりも、退屈だろう",
    "影子里还藏着几颗，下次再数。": "影の中にまだ何個か隠してある、また今度数える。",
    "往云团中间扔块石头（55% 获得 1 张稀有卡 / 45% -20 HP）": "雲の塊の真ん中に石を投げる（55% レアカード 1 枚を獲得 / 45% -20 HP）",
    "往后每加一只宝可梦，都会一并配好它自己的口吻台词（这是硬性要求，缺了出不了包）。": "これからポケモンを追加するときは、その子自身の口調の台詞も必ず一緒に用意する（必須ルールで、欠けると出荷できない）。",
    "往岩缝里挤！": "岩の隙間に押し込む！",
    "往岩缝里挤（-10 HP，防御 +4）": "岩の隙間に押し込む（HP -10、防御 +4）",
    "往旁边让开，等它自己掉（敏捷 +3）": "横にどいて、自然に落ちるのを待つ（敏捷 +3）",
    "往里挖挖看。": "中を掘ってみる。",
    "往里挖（55% 获得道具 / 45% -20 HP）": "中を掘る（55% アイテム獲得 / 45% -20 HP）",
    "往高处跑！": "高い場所へ走れ！",
    "往高处跑（-12 HP，敏捷 +4）": "高い場所へ走る（HP -12、敏捷 +4）",
    "很疼。但冷却之后，甲壳上多了一层像釉的东西。\n「呜……好疼呀。不过变硬了。」\nHP -{hp}，防御 +5。": "すごく痛い。でも冷えたあと、甲殻にうわぐすりのような層ができていた。\n「うぅ……痛いよぉ。でも硬くなった。」\nHP -{hp}、防御 +5。",
    "很难喝。但它把你身体里攒的那些沙子泡开了，你吐出来一堆。\n「呸呸呸……不过好像轻快了。」\nHP +{heal}。": "まずい。でも体にたまった砂をふやかしてくれたので、まとめて吐き出せた。\n「ぺっぺっぺ……でも、なんだか軽くなった。」\nHP +{heal}。",
    "得再攒一炉子烟，明天接着冒。": "また煙をひと炉ぶん溜めて、明日も噴こう。",
    "快捷键": "ショートカットキー",
    "快点离开灯市": "灯市を急いで離れる",
    "快速抽牌": "クイックドロー",
    "念力": "ねんりき",
    "念力一用，整个身子都轻飘飘的。": "念力を使うと、体がふわふわするんだ。",
    "念力土偶": "ネンドール",
    "念着谁也听不懂的咒，站在路中间。": "誰にも分からない呪文を唱えながら、道の真ん中に立っている。",
    "怎么打": "戦い方",
