    "（背景调整，玩法上看不出来）敌人的输出系数回落到原来的水位：卡牌整体变强之后，两边一起变强就等于没变。": "（裏側の調整で、プレイ上は見えない）敵の出力係数を元の水準に戻した：カード全体が強くなったので、両方が一緒に強くなると結局変わらないことになる。",
