    "「**子弹拳**」不再是「电光一闪」的翻版：它改成 0 费、30 威力并**无视对手 30% 防御**（它是稀有卡，本来就该有自己的东西）。": "\"**Bullet Punch**\" is no longer a copy of Quick Attack: it is now 0 cost, 30 power and **ignores 30% of the foe's Defense** (it is a rare card, so it deserves something of its own).",
