    "布歪了也没关系，你肯留下吗": "Even crooked, I just want you to stay.",
    "带电的风": "Charged Wind",
    "带粗体的是这一版最值得看的几件事。": "Bold entries are the highlights of that version.",
    "带走一颗果子（获得好伤药 ×2）": "Take a fruit with you (Gain Potion ×2)",
    "带进战斗的就是你拥有的全部卡牌 —— 不能挑着不带，也不能只带两张。": "Everything you own goes into battle — you can't leave cards out, and you can't bring just two.",
    "干干净净一根，商人都认得这个价钱。": "A single clean one; every merchant knows what it's worth.",
