    "造成 {d} 点伤害，无视对手 50% 防御。使用后销毁。": "Deal {d} damage, ignoring 50% of the foe's Defense. Exhaust.",
    "造成 {d} 点伤害，无视对手 70% 防御。": "Deal {d} damage, ignoring 70% of the foe's Defense.",
