    "音频文件按原样使用，未做改编；循环点用的是文件自带的循环标记。": "Audio files are used as published, with no arrangement; loops use the loop markers built into each file.",
    "顶过最猛的那一段，风突然就软了。你站在风眼当中，浑身都是电，连爪子抬起来的时候都在响。\n「哈，撑过来啦！」\n攻击 +4。": "You push through the worst of it, and the wind suddenly goes soft. Standing in the eye of it, you're full of current —— even lifting a claw makes it crackle.\n\"Ha! Made it through!\"\nAttack +4.",
    "顺便把卡理一理。": "Tidy up your cards while you're at it.",
    "顺带把**全部文案彻查了一遍**（卡牌 / 物品 / 事件 / 敌人台词 / 更新日志 / 三语字典，共 1691 段），没有别的残留。": "Went through **all copy** while at it (cards / items / events / enemy lines / changelog / all three dictionaries, 1691 strings) — nothing else was left over.",
    "顺手修掉了 5 只把「超能」写成「超能力」的宝可梦（会让它们挑不到自己属性的招式）。": "Also fixed 5 Pokémon whose type was misspelled (which stopped them from picking moves of their own type).",
    "顺着坡滑下去（-15 HP，获得 1 张卡）": "Slide down the slope (-15 HP, gain 1 card)",
    "顺着峡谷一路跑下来，风都是热的。": "It comes sprinting down the canyon, and the wind is already hot.",
    "顺着沙流滑下去（敏捷 +2）": "Ride the sand flow down (Agility +2)",
    "顺着沟研究它怎么打的（攻击 +2，敏捷 +2）": "Study the furrows to see how it fought (Attack +2, Agility +2)",
    "顺着潮水贴地游，看着懒散其实很快。": "It swims low along the current, looking lazy and moving fast.",
    "顺着藤蔓爬到顶上。": "Climb the vines to the top.",
    "顺着藤蔓爬到顶上（最大生命 +16）": "Climb the vines to the top (max HP +16)",
    "顺着那条线滑过去！": "Glide along that line!",
    "顺着那条线滑过去（-12 HP，敏捷 +5）": "Glide along that line (-12 HP, Agility +5)",
    "顺着陡坡滚，越滚越快，不打算停。": "It rolls down the steep slope, gathering speed, with no intention of stopping.",
    "顺风": "Tailwind",
    "顽皮雷弹": "Electrode",
    "预知未来": "Future Sight",
    "风上的铁骑士": "Iron Knight of the Wind",
    "风从台地那头刮过来，刮到脸上有一点刺。你顺着风看过去，风里的沙全都竖着飘 —— 像被谁拎住了。\n「唔，风里带电呀。我头发都……哦，我没有头发。」": "The wind comes in off the far side of the plateau, stinging a little against your face. You follow it with your eyes and see the sand all drifting upward —— as if something is holding it up.\n\"Mm, the wind's got current in it. My hair's all... oh, right. I don't have hair.\"",
    "风从翅膀底下过，我借它的力。": "The wind slips under my wings, and I ride it.",
    "风从耳边过的时候，它才觉得自己活着。": "Wind in my ears, that's when I feel alive.",
    "风停了半秒 —— 因为它正好挡在你和太阳之间。": "The wind stops for half a second — because it is sitting right between you and the sun.",
    "风停的时候，我听见了你的脚步": "When the wind stops, I can hear your steps.",
    "风吹过沙丘顶，沙子发出很像歌声的嗡鸣。\n「唔……这个调子我会呀。」": "Wind crosses the crest of the dune, and the sand hums something very like a song.\n\"Hmm... I know this tune.\"",
    "风在这里被切成一把把刀。岩壁上全是它刻出来的沟，深得能塞进一个人。": "Here the wind is cut into blades. The cliffs are scored with the grooves it carved — deep enough to hold a person.",
    "风太大了，我还是回崖上躲躲。": "Too windy. I'll go hide up on the cliff.",
    "风已经停了，我这翅膀该歇歇了。": "Wind's still, time to rest these wings.",
    "风总会变的，胜负早晚也一样。": "The wind always changes. So does winning and losing.",
    "风把云吹开一条缝。缝里露出来的东西你只看了半秒就明白了 —— 那是一条路，只是铺在天上。你把这半秒记住，顺手抄进了卡组。\n「路在天上呀。……那我以后也能飞上去咯？」\n获得「{card}」。": "The wind peels the clouds back into a thin gap. What shows through, you understand in half a second —— that's a road, just paved up in the sky. You hold onto that half second, and copy it into your deck while you're at it.\n\"A road up in the sky. ...So I could fly up there someday too?\"\nYou gain \"{card}\".",
    "风把它托在崖口，它没有扇翅膀。": "The wind holds it at the cliff edge, and it never flaps its wings.",
    "风比你想的重。你被推回来三次，最后一次是滚回来的，甲壳上落了一层烧黑的沙。\n「呜！……下次逆风我不走了。」\nHP -{hp}。": "The wind is heavier than you thought. It shoves you back three times, and the last time you come back rolling, a layer of scorched sand settling on your shell.\n\"Ngh! ...Next time the wind's against me, I'm not walking.\"\nHP -{hp}.",
    "风的口子": "The Wind's Gap",
    "风突然换了方向，从背后把你拍在岩壁上，拍了好几下。\n「呜！风也会翻脸呀……」\nHP -{hp}。": "The wind suddenly changes direction and slams you against the rock wall — again and again.\n\"Ow! The wind turns on you too...\"\nHP -{hp}.",
    "风蚀峭壁": "Wind-Eroded Cliffs",
